    while (map.has(cur) && !seen.has(cur)) {
        seen.add(cur);
        const value = map.get(cur)!;
        const alias = value.match(/^var\(\s*(--[\w-]+)\s*\)$/);
        if (!alias) return value;
        cur = alias[1]!;
    }
    return map.get(cur) ?? cur;
